#include <vector>
#include <queue>

using namespace std;

class Solution {
public:
    vector<int> sequentialDigits(int low, int high) {
        queue<int> q;
        for (int i = 1; i <= 9; ++i)
            q.push(i);

        vector<int> res;
        while (!q.empty()) {
            int num = q.front(); q.pop();
            if (num >= low && num <= high) res.push_back(num);
            if (num % 10 < 9) {
                int next = num * 10 + (num % 10 + 1);
                if (next <= high) q.push(next);
            }
        }
        return res;
    }
};
